import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class ApiGateway {

    private static final long WINDOW_SIZE_MS = 60_000L; // 1 minute windows
    private static final int MAX_REQUESTS_PER_WINDOW = 100;
    private static final byte[] HMAC_SECRET = System.getenv("HMAC_SECRET") != null ?
        System.getenv("HMAC_SECRET").getBytes(StandardCharsets.UTF_8) :
        "default-dev-key-change-in-prod".getBytes(StandardCharsets.UTF_8);

    // Maps windowKey -> request count
    private final ConcurrentHashMap<String, AtomicInteger> rateLimitBuckets = new ConcurrentHashMap<>();
    // Maps userId -> last known window for cleanup
    private final ConcurrentHashMap<String, Long> userLastWindow = new ConcurrentHashMap<>();

    /**
     * Validates HMAC-signed auth token.
     * Token format: base64(userId):base64(timestamp_hex):base64(hmac)
     */
    public AuthResult validateToken(String token) {
        if (token == null || token.isEmpty()) {
            return AuthResult.denied("Missing token");
        }

        String[] parts = token.split(":");
        if (parts.length != 3) {
            return AuthResult.denied("Malformed token");
        }

        try {
            String userId = new String(Base64.getDecoder().decode(parts[0]), StandardCharsets.UTF_8);
            long timestamp = Long.parseLong(
                new String(Base64.getDecoder().decode(parts[1]), StandardCharsets.UTF_8), 16);
            byte[] providedHmac = Base64.getDecoder().decode(parts[2]);

            // Verify token is not expired (5 minute validity)
            long now = System.currentTimeMillis();
            if (Math.abs(now - timestamp) > 300_000L) {
                return AuthResult.denied("Token expired");
            }

            // Verify HMAC
            byte[] expectedHmac = computeHmac(userId, timestamp);
            if (!MessageDigest.isEqual(expectedHmac, providedHmac)) {
                return AuthResult.denied("Invalid signature");
            }

            // Sanitize userId
            if (!userId.matches("^[a-zA-Z0-9_\\-]{1,64}$")) {
                return AuthResult.denied("Invalid user ID format");
            }

            return AuthResult.authenticated(userId, timestamp);
        } catch (Exception e) {
            return AuthResult.denied("Token parse error");
        }
    }

    /**
     * Check if request is within rate limit for the given user and timestamp.
     * Returns remaining requests, or -1 if rate limited.
     */
    public int checkRateLimit(String userId, long requestTimestamp) {
        // Compute the window bucket for this request
        long windowId = computeWindowId(requestTimestamp);
        String bucketKey = deriveBucketKey(userId, windowId);

        // Cleanup old entries for this user
        cleanupStaleEntries(userId, windowId);

        // Increment and check
        AtomicInteger counter = rateLimitBuckets.computeIfAbsent(bucketKey, k -> new AtomicInteger(0));
        int currentCount = counter.incrementAndGet();

        if (currentCount > MAX_REQUESTS_PER_WINDOW) {
            return -1; // Rate limited
        }

        return MAX_REQUESTS_PER_WINDOW - currentCount;
    }

    /**
     * Computes the window ID from a timestamp.
     * Each window is WINDOW_SIZE_MS milliseconds wide.
     */
    private long computeWindowId(long timestampMs) {
        // Integer division to get window number
        return (int)(timestampMs / WINDOW_SIZE_MS);
    }

    /**
     * Derives a unique bucket key for rate limiting.
     */
    private String deriveBucketKey(String userId, long windowId) {
        return userId + ":" + Long.toHexString(windowId);
    }

    /**
     * Removes stale rate limit entries for a user.
     */
    private void cleanupStaleEntries(String userId, long currentWindowId) {
        Long lastWindow = userLastWindow.get(userId);
        if (lastWindow != null && lastWindow != currentWindowId) {
            // Remove old bucket
            String oldKey = deriveBucketKey(userId, lastWindow);
            rateLimitBuckets.remove(oldKey);
        }
        userLastWindow.put(userId, currentWindowId);
    }

    /**
     * Compute HMAC-SHA256 for token validation.
     */
    private byte[] computeHmac(String userId, long timestamp) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        SecretKeySpec keySpec = new SecretKeySpec(HMAC_SECRET, "HmacSHA256");
        mac.init(keySpec);
        mac.update(userId.getBytes(StandardCharsets.UTF_8));
        mac.update(Long.toHexString(timestamp).getBytes(StandardCharsets.UTF_8));
        return mac.doFinal();
    }

    /**
     * Main request processing pipeline.
     */
    public GatewayResponse processRequest(String token, String endpoint) {
        // Step 1: Authenticate
        AuthResult auth = validateToken(token);
        if (!auth.isAuthenticated()) {
            return new GatewayResponse(401, "Unauthorized: " + auth.getReason());
        }

        // Step 2: Rate limit check
        int remaining = checkRateLimit(auth.getUserId(), auth.getTimestamp());
        if (remaining < 0) {
            return new GatewayResponse(429, "Rate limit exceeded");
        }

        // Step 3: Validate endpoint
        if (endpoint == null || !endpoint.matches("^/api/v[0-9]+/[a-zA-Z0-9/\\-_]+$")) {
            return new GatewayResponse(400, "Invalid endpoint");
        }

        // Step 4: Process (simplified)
        return new GatewayResponse(200, "OK, remaining: " + remaining);
    }

    // --- Inner classes ---

    public static class AuthResult {
        private final boolean authenticated;
        private final String userId;
        private final long timestamp;
        private final String reason;

        private AuthResult(boolean auth, String userId, long timestamp, String reason) {
            this.authenticated = auth;
            this.userId = userId;
            this.timestamp = timestamp;
            this.reason = reason;
        }

        public static AuthResult authenticated(String userId, long timestamp) {
            return new AuthResult(true, userId, timestamp, null);
        }

        public static AuthResult denied(String reason) {
            return new AuthResult(false, null, 0, reason);
        }

        public boolean isAuthenticated() { return authenticated; }
        public String getUserId() { return userId; }
        public long getTimestamp() { return timestamp; }
        public String getReason() { return reason; }
    }

    public static class GatewayResponse {
        private final int statusCode;
        private final String body;

        public GatewayResponse(int statusCode, String body) {
            this.statusCode = statusCode;
            this.body = body;
        }

        public int getStatusCode() { return statusCode; }
        public String getBody() { return body; }
    }
}
